window.CC.p.push({n:14,view:"<section class=\"view\" id=\"p14\" hidden style=\"--c:#546e7a\"><h1><i>14</i>Urology</h1><p class=\"lead\">20 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 14A</h3><div class=\"card\" data-u=\"u355\"><button class=\"open\" data-u=\"u355\"><b>Case 1</b><span>Benign Prostatic Hyperplasia (BPH)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Benign+Prostatic+Hyperplasia+%28BPH%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u356\"><button class=\"open\" data-u=\"u356\"><b>Case 2</b><span>Acute Urinary Retention (AUR) &amp; Foley Catheterization Mastery</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Urinary+Retention+%28AUR%29+%26+Foley+Catheterization+Mastery\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u357\"><button class=\"open\" data-u=\"u357\"><b>Case 3</b><span>Acute &amp; Chronic Prostatitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+%26+Chronic+Prostatitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u358\"><button class=\"open\" data-u=\"u358\"><b>Case 4</b><span>Acute Scrotum — Testicular Torsion vs. Epididymo-Orchitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Scrotum+%E2%80%94+Testicular+Torsion+vs.+Epididymo-Orchitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u359\"><button class=\"open\" data-u=\"u359\"><b>Case 5</b><span>Hydrocele, Spermatocele &amp; Varicocele</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hydrocele%2C+Spermatocele+%26+Varicocele\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u360\"><button class=\"open\" data-u=\"u360\"><b>Case 6</b><span>Priapism (ISCHEMIC VS. NON-ISCHEMIC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Priapism+%28ISCHEMIC+VS.+NON-ISCHEMIC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u361\"><button class=\"open\" data-u=\"u361\"><b>Case 7</b><span>Phimosis, Paraphimosis &amp; Balanoposthitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Phimosis%2C+Paraphimosis+%26+Balanoposthitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u362\"><button class=\"open\" data-u=\"u362\"><b>Case 8</b><span>Fournierʼs Gangrene (PERINEAL NECROTIZING FASCIITIS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Fournier%CA%BCs+Gangrene+%28PERINEAL+NECROTIZING+FASCIITIS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u363\"><button class=\"open\" data-u=\"u363\"><b>Case 9</b><span>Urethritis &amp; Urethral Stricture</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urethritis+%26+Urethral+Stricture\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u364\"><button class=\"open\" data-u=\"u364\"><b>Case 10</b><span>Erectile Dysfunction (ED) &amp; Peyronieʼs Disease</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Erectile+Dysfunction+%28ED%29+%26+Peyronie%CA%BCs+Disease\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 14B</h3><div class=\"card\" data-u=\"u365\"><button class=\"open\" data-u=\"u365\"><b>Case 11</b><span>Bladder Carcinoma (UROTHELIAL VS. BILHARZIAL SQUAMOUS CELL CARCINOMA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bladder+Carcinoma+%28UROTHELIAL+VS.+BILHARZIAL+SQUAMOUS+CELL+CARCINOMA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u366\"><button class=\"open\" data-u=\"u366\"><b>Case 12</b><span>Urinary Schistosomiasis (SCHISTOSOMA HAEMATOBIUM — EGYPTIAN CLASSIC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urinary+Schistosomiasis+%28SCHISTOSOMA+HAEMATOBIUM+%E2%80%94+EGYPTIAN+CLASSIC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u367\"><button class=\"open\" data-u=\"u367\"><b>Case 13</b><span>Prostate Carcinoma</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Prostate+Carcinoma\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u368\"><button class=\"open\" data-u=\"u368\"><b>Case 14</b><span>Renal Cell Carcinoma (RCC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal+Cell+Carcinoma+%28RCC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u369\"><button class=\"open\" data-u=\"u369\"><b>Case 15</b><span>Testicular Tumors (GERM CELL TUMORS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Testicular+Tumors+%28GERM+CELL+TUMORS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u370\"><button class=\"open\" data-u=\"u370\"><b>Case 16</b><span>Renal Trauma &amp; Bladder Rupture</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal+Trauma+%26+Bladder+Rupture\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u371\"><button class=\"open\" data-u=\"u371\"><b>Case 17</b><span>Urethral Trauma (ANTERIOR VS. POSTERIOR)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urethral+Trauma+%28ANTERIOR+VS.+POSTERIOR%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u372\"><button class=\"open\" data-u=\"u372\"><b>Case 18</b><span>Obstructive Uropathy &amp; Hydronephrosis (PUJ OBSTRUCTION)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Obstructive+Uropathy+%26+Hydronephrosis+%28PUJ+OBSTRUCTION%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u373\"><button class=\"open\" data-u=\"u373\"><b>Case 19</b><span>Pediatric Urology — Cryptorchidism, Hypospadias &amp; PUV</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Urology+%E2%80%94+Cryptorchidism%2C+Hypospadias+%26+PUV\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u374\"><button class=\"open\" data-u=\"u374\"><b>Case 20</b><span>Nocturnal Enuresis &amp; Neurogenic Bladder</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nocturnal+Enuresis+%26+Neurogenic+Bladder\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u355\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Benign Prostatic Hyperplasia (BPH)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Benign+Prostatic+Hyperplasia+%28BPH%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><mark class=\"hl lab\"><b>BPH</b></mark> (Benign Prostatic Hyperplasia) is non-malignant stromal and epithelial hyperplasia of the <b>transitional (periurethral) zone</b> of the prostate gland in aging men, causing bladder outlet obstruction and <b>LUTS</b> (Lower Urinary Tract Symptoms). <i>(Affects &gt; 50% of men &gt; 60 yrs and ~80–90% &gt; 80 yrs!)</i></p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Hormonal Mechanism (Primary Driver):</b> Testosterone is converted inside prostatic stromal cells by <b>5-alpha-reductase (Type 2)</b> into the potent androgen <b>DHT </b>(Dihydrotestosterone), driving progressive cellular proliferation.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Dynamic Muscular Component:</b> Increased α1-adrenergic smooth muscle tone in the prostate capsule and bladder neck.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Host Risk Factors:</b> Advancing age (mandatory!), obesity, metabolic syndrome / <mark class=\"hl lab\"><b>T2DM</b></mark> (Type 2 Diabetes Mellitus), family history. <i>(Note: BPH is </i><i><b>NOT</b></i><i> a premalignant lesion for Prostate Cancer, which arises in the </i><i><b>peripheral zone</b></i><i>!)</i></span></p><h3><b>3. Pathophysiology</b></h3><p>Static mechanical compression (enlarged periurethral adenomas) + dynamic α1-mediated smooth muscle constriction narrow the prostatic urethra -&gt; detrusor muscle hypertrophies (bladder trabeculation/diverticula) -&gt; eventual detrusor decompensation, incomplete bladder emptying, and <b>overflow incontinence</b> or <b>bilateral hydronephrosis</b>.</p><h3><b>4. Clinical Picture (LUTS: Voiding vs. Storage Symptoms)</b></h3><ul>\n<li class=\"l1\"><b>Voiding (Obstructive) Symptoms:</b> <b>Hesitancy</b> (waiting to start stream), <b>weak/thin urinary stream</b>, straining, intermittency (stop-start), sensation of incomplete emptying, post-void dribbling.</li>\n<li class=\"l1\"><b>Storage (Irritative) Symptoms:</b> Urinary <b>frequency</b>, <b>urgency</b>, <b>nocturia</b> (waking multiple times at night).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>DRE</b></mark> (Digital Rectal Exam): <b>Smooth, symmetrically enlarged, firm-rubbery, non-tender prostate</b> with <b>obliterated median sulcus</b> <i>(contrast with Prostate Cancer: hard, irregular, asymmetric </i><i><b>nodule</b></i><i>!)</i></li>\n<li class=\"l1\"><b>Quantify Severity:</b> <b>IPSS</b> (International Prostate Symptom Score: Mild 0–7, Moderate 8–19, Severe 20–35).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Urinalysis</b></mark> (MANDATORY in ALL men with LUTS — rule out <b>UTI</b> [Urinary Tract Infection] and <b>hematuria</b>!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Serum Creatinine / RFTs</b></mark> (Renal Function Tests — rule out obstructive uropathy!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Serum PSA</b></mark> (Prostate-Specific Antigen — offer after shared decision-making in men 55–69 yrs or if abnormal DRE; <i>remember BPH itself mildly raises PSA!</i>).</li>\n<li class=\"l1\"><b>Pelvic / Abdominal Ultrasound with Post-Void Residual (PVR) Volume:</b> Measures prostate size, PVR (&gt; 100–150 mL abnormal), and checks kidneys for <b>hydronephrosis</b>!</li>\n<li class=\"l1\"><b>Uroflowmetry</b> (Qmax &lt; 10–15 mL/sec indicates obstruction).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Prostate carcinoma, Urethral stricture, Acute/Chronic prostatitis, Bladder stone or Bladder tumor (especially if hematuria/irritative symptoms predominate!), Neurogenic bladder (diabetic neuropathy), Drug-induced retention (anticholinergics, antihistamines, decongestants!).</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Acute Urinary Retention (AUR)</b></mark> , Recurrent UTIs, <b>Bladder calculi</b> (stasis), Gross painless hematuria (fragile prostatic varices), <mark class=\"hl lab\"><b>Bilateral Hydronephrosis &amp; Post-Renal AKI/CKD</b></mark> (Acute/Chronic Kidney Injury), Bladder diverticula.</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Mild Symptoms (IPSS &lt; 8) &amp; No Complications:</b> Watchful waiting + lifestyle changes (limit evening fluids, avoid caffeine/alcohol/decongestants, \"double voiding\").</li>\n<li class=\"l1\"><b>Moderate-to-Severe LUTS (Medical Therapy):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Alpha-1 Adrenergic Blockers (First-Line — Fast Relief Within Days!):</b> <b>Tamsulosin 0.4 mg</b> or <b>Silodosin</b> (uroselective α1A -&gt; minimal hypotension, <i>but causes </i><i><b>retrograde ejaculation</b></i><i> and </i><i><b>Intraoperative Floppy Iris Syndrome</b></i><i> during cataract surgery!</i>); <b>Alfuzosin, Terazosin, Doxazosin</b> (also lower BP!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl mech\"><b>5-Alpha-Reductase Inhibitors (5-ARIs — Add if Large Prostate &gt; 30–40 g or PSA &gt; 1.5 ng/mL!):</b></mark> <b>Finasteride 5 mg</b> or <b>Dutasteride 0.5 mg</b> daily (shrinks prostate by ~25% and reduces AUR/surgery risk, <b>takes 6–12 MONTHS for full effect</b> and <mark class=\"hl mech\"><b>halves serum PSA</b></mark> — <i>always DOUBLE measured PSA after 6 mos on Finasteride!</i> Warn about decreased libido/ED).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Combination (Alpha-blocker + 5-ARI):</b> Gold standard for large symptomatic prostates! (<b>Tadalafil 5 mg</b> daily if concurrent Erectile Dysfunction; cautious <b>Antimuscarinics/Mirabegron</b> if predominant overactive bladder + low PVR!).</span></p>\n<ul>\n<li class=\"l1\"><b>Absolute Indications for Surgery (TURP [Transurethral Resection of the Prostate] / HoLEP / Open Prostatectomy if &gt; 80–100 g):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Refractory Acute Urinary Retention</b></mark> (failed Trial Without Catheter!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Recurrent UTIs</b> or <b>Bladder Stones</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Recurrent Gross Hematuria</b> refractory to 5-ARIs.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Renal Insufficiency / Bilateral Hydronephrosis</b> from BPH!</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\">Symptoms refractory to maximal medical therapy!</span></p><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u356\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u356\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Acute Urinary Retention (AUR) &amp; Foley Catheterization Mastery</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Urinary+Retention+%28AUR%29+%26+Foley+Catheterization+Mastery\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Sudden, <b>painful inability to pass any urine</b> despite a full, distended bladder (<b>True Urological Emergency</b>!).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Mechanical Outlet Obstruction:</b> <mark class=\"hl lab\"><b>BPH (#1 Overall Cause in Men!)</b></mark> , Urethral stricture, Blood clots (\"clot retention\" from bladder/prostate bleed!), Bladder neck stone, Phimosis, Impacted pelvic mass/fecal impaction.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Pharmacologic / Triggered in BPH Patients:</b></mark> <b>First-generation Antihistamines</b> (flu pills!), <b>Decongestants</b> (Pseudoephedrine), <b>Anticholinergics</b>, <b>Opioids</b>, <b>TCAs </b>(Tricyclic Antidepressants), Alcohol, Post-operative anesthesia pain!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Infectious / Inflammatory:</b> Acute Prostatitis, Severe Herpes/Urethritis.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Neurologic:</b> <b>Cauda Equina Syndrome</b> (MUST check saddle sensation &amp; anal tone!), Spinal cord compression, Diabetic cystopathy.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Agonizing <b>suprapubic pain</b>, restlessness, inability to void for hours; exam reveals a <b>smooth, tense, dull, exquisitely tender palpable suprapubic mass</b> (percusses dull!). <i>(Contrast with </i><i><b>Anuria</b></i><i>: empty bladder on ultrasound, NO suprapubic pain!)</i></li>\n</ul><h3><b>4. Emergency Treatment (Decompress Bladder Immediately!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Aseptic Transurethral Foley Catheterization (16–18Fr)</b> using generous <mark class=\"hl rx\"><b>2% Lidocaine lubricating gel</b></mark> instilled into urethra (wait 3–5 min before passing!).</span></p>\n<ul>\n<li class=\"l2\"><i>If Large Prostate Fails Standard Foley:</i> Try a stiffer <b>Coudé-Tipped (curved) Catheter</b> (tip pointing upward/anteriorly!).</li>\n<li class=\"l2\"><i>CRITICAL CONTRAINDICATION TO BLIND FOLEY:</i> <b>Pelvic trauma with blood at urethral meatus</b>, OR known tight <b>urethral stricture</b> where catheter meets firm resistance (NEVER force a Foley — causes fatal false passages!) -&gt; <mark class=\"hl mech\"><b>Call Urology for Cystoscopy or Ultrasound-Guided Suprapubic Catheter (SPC)!</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Decompression Myth Busted:</b> Allow <b>free continuous drainage</b> (gradual clamping is no longer required!), <i>but</i> monitor closely for <b>Post-Obstructive Diuresis</b> (urine output &gt; 200 mL/hr for &gt; 2 hrs -&gt; replace 50% of excess urine output with IV 0.45% or 0.9% Saline and check <b>K+/Na+/Mg++</b>!) and transient self-limited hematuria!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>TWOC (Trial Without Catheter):</b> Start <b>Tamsulosin 0.4 mg daily</b> immediately -&gt; attempt catheter removal in <b>3–7 days</b> (~50–60% void successfully if BPH-triggered!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u355\">← Case 1</button><button class=\"nv\" data-u=\"u357\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u357\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Acute &amp; Chronic Prostatitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+%26+Chronic+Prostatitis\">🔍 Search on Google</a></header><h3><b>1. Classification (NIH Categories I–IV)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Category I — Acute Bacterial Prostatitis (Medical Emergency!).</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Category II — Chronic Bacterial Prostatitis</b> (recurrent UTIs with same organism).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Category III — Chronic Prostatitis / Chronic Pelvic Pain Syndrome (CP/CPPS — &gt; 90% of Chronic Cases!):</b> Non-bacterial pelvic pain &gt; 3 months.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Category IV — Asymptomatic Inflammatory Prostatitis</b> (incidental biopsy/semen finding).</span></p><h3><b>2. Etiology of Bacterial Prostatitis (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Enteric Gram-Negative Rods (#1 Overall):</b> <i><b>Escherichia coli</b></i> (~75%), <i>Klebsiella</i>, <i>Proteus</i>, <i>Pseudomonas</i> (ascending urethral reflux or post-prostate biopsy/catheter!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Sexually Transmitted (Young Men &lt; 35 Yrs):</b> <i>Chlamydia trachomatis</i>, <i>Neisseria gonorrhoeae</i>.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Acute Bacterial Prostatitis:</b> Sudden <b>high fever, chills</b>, <b>perineal/low back pain</b>, severe <b>dysuria, frequency, urgency</b>, obstructive symptoms (may cause <b>AUR!</b>).</li>\n<li class=\"l2\"><b>DRE:</b> <mark class=\"hl lab\"><b>EXQUISITELY TENDER, WARM, SWOLLEN, \"BOGGY\" PROSTATE!</b></mark></li>\n<li class=\"l2\"><b>GOLDEN SAFETY RULE:</b> <b>NEVER VIGOROUSLY MASSAGE AN ACUTELY INFLAMED PROSTATE</b> — risks precipitating <b>fatal Bacteremia / Septic Shock</b>!</li>\n<li class=\"l1\"><b>Chronic Bacterial Prostatitis:</b> Afebrile; recurrent UTIs + dull perineal/ejaculatory ache + dysuria between flares!</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Workup:</b> <b>Midstream Urine Analysis &amp; Culture</b>, <b>Blood Cultures</b> (if febrile/toxic), <mark class=\"hl mech\"><b>CBC</b></mark> ; if failing antibiotics at 48–72 hrs -&gt; <b>Transrectal Ultrasound (TRUS) or CT Pelvis</b> to rule out <b>Prostatic Abscess</b> (needs drainage!).</li>\n<li class=\"l1\"><b>Treatment (Requires Fat-Soluble Antibiotics That Penetrate the Prostate + Prolonged Duration!):</b></li>\n<li class=\"l2\"><i>Acute Severe / Septic:</i> <mark class=\"hl rx\"><b>IV Ceftriaxone</b></mark> (or Piperacillin-Tazobactam / Ciprofloxacin + Gentamicin) -&gt; switch to <mark class=\"hl rx\"><b>Oral Ciprofloxacin / Levofloxacin</b></mark> or <b>TMP-SMX </b>for <b>2–4 WEEKS</b>! <i>(If </i><i><b>AUR</b></i><i> occurs -&gt; prefer </i><i><b>Suprapubic Catheter</b></i><i> or gentle small 12Fr Foley!)</i></li>\n<li class=\"l2\"><i>Chronic Bacterial Prostatitis:</i> <mark class=\"hl rx\"><b>Fluoroquinolone (Ciprofloxacin/Levofloxacin)</b></mark> or <b>TMP-SMX</b> for <b>4–6 WEEKS</b>!</li>\n<li class=\"l2\"><i>CP/CPPS (Non-bacterial):</i> Alpha-blocker (Tamsulosin) + NSAIDs + warm Sitz baths + pelvic floor physiotherapy!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u356\">← Case 2</button><button class=\"nv\" data-u=\"u358\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u358\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Acute Scrotum — Testicular Torsion vs. Epididymo-Orchitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Scrotum+%E2%80%94+Testicular+Torsion+vs.+Epididymo-Orchitis\">🔍 Search on Google</a></header><p><i>(TRUE SURGICAL EMERGENCY: </i><mark class=\"hl lab\"><i><b>Testicular Torsion Must Be Detorsed Within 6 HOURS to Save Testicular Viability!</b></i></mark><i> )</i></p><h4><b>High-Yield Clinical Differentiation Matrix</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><mark class=\"hl lab\"><b>Testicular Torsion </b></mark><i><b>(EMERGENCY!)</b></i></p></th><th><p><b>Acute Epididymo-Orchitis</b></p></th><th><p><b>Torsion of Appendix Testis</b></p></th></tr><tr><td><p><b>Peak Age</b></p></td><td><p><b>Neonates &amp; Adolescents (12–18 yrs) </b>(also young adults; <b>\"Bell-Clapper\" anatomical deformity!</b>)</p></td><td><p><b>Sexually active men (&lt; 35 yrs)</b> &amp; <b>Older men (&gt; 35 yrs)</b></p></td><td><p><b>Prepubertal boys (7–12 yrs)</b></p></td></tr><tr><td><p><b>Etiology</b></p></td><td><p>Mechanical twisting of spermatic cord (venous then arterial ischemia!)</p></td><td><p><i>&lt; 35 yrs:</i> <b>Chlamydia / Gonorrhea</b> | <i>&gt; 35 yrs / BPH:</i> <i><b>E. coli</b></i><b> / UTI</b> | <i>Post-pubertal viral:</i> <b>Mumps</b>!</p></td><td><p>Ischemic twist of vestigial Müllerian remnant at upper pole</p></td></tr><tr><td><p><b>Onset &amp; Pain</b></p></td><td><p><b>SUDDEN, EXPLOSIVE, SEVERE</b> scrotal pain (often waking from sleep!) + <b>Nausea &amp; Vomiting</b></p></td><td><p><b>GRADUAL</b> onset over hours–days; dysuria, frequency, urethral discharge, <b>Fever</b>!</p></td><td><p>Acute/subacute pain localized strictly to <b>upper pole of testis</b></p></td></tr><tr><td><p><b>Scrotal Exam</b></p></td><td><p><b>High-riding, HORIZONTAL (\"transverse\") testis</b>, swollen/tender; <mark class=\"hl mech\"><b>ABSENT CREMASTERIC REFLEX!</b></mark></p></td><td><p>Normal vertical lie; tender swollen <b>posterior epididymis</b>; <b>INTACT Cremasteric Reflex</b></p></td><td><p><b>\"Blue Dot Sign\"</b> visible through upper scrotal skin; <b>INTACT Cremasteric Reflex</b></p></td></tr><tr><td><p><b>Prehn’s Sign</b> <i>(Lifting scrotum)</i></p></td><td><p>Pain <b>NOT relieved</b> (or worsens!)</p></td><td><p>Pain <b>RELIEVED</b> by elevation! <i>(Unreliable alone — NEVER delay torsion care for Prehn’s!)</i></p></td><td><p>Variable</p></td></tr><tr><td><p><b>Diagnostic Tool</b></p></td><td><p><b>DO NOT DELAY SURGERY FOR ULTRASOUND IF CLASSIC!</b> <i>(Color Doppler shows </i><i><b>ABSENT intratesticular blood flow</b></i><i>)</i></p></td><td><p><b>Color Doppler US shows INCREASED blood flow</b>; <mark class=\"hl mech\"><b>Urinalysis + Urine Culture + GC/Chlamydia NAAT</b></mark> !</p></td><td><p>Normal testicular flow + avascular upper pole nodule</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><mark class=\"hl mech\"><b>EMERGENT SURGICAL EXPLORATION (&lt; 6 hrs): Detorsion + BILATERAL ORCHIOPEXY</b></mark> (fix contralateral testis too — bell-clapper is bilateral! Orchiectomy if necrotic!)</p></td><td><p><mark class=\"hl rx\"><b>Rest, Scrotal Elevation, Ice, NSAIDs + Antibiotics:</b></mark> <i>&lt; 35 yrs (STI):</i> <mark class=\"hl rx\"><b>IM Ceftriaxone 500 mg + Doxycycline 100 mg BID × 10 days</b></mark> | <i>&gt; 35 yrs (Enteric): </i><b>Levofloxacin/Ofloxacin × 10 days</b>!</p></td><td><p><b>Self-limited!</b> Rest + NSAIDs + ice</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u357\">← Case 3</button><button class=\"nv\" data-u=\"u359\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u359\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Hydrocele, Spermatocele &amp; Varicocele</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hydrocele%2C+Spermatocele+%26+Varicocele\">🔍 Search on Google</a></header><h4><b>High-Yield Scrotal Mass Differentiation (Can You Get ABOVE the Swelling? Does It Transilluminate?)</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Mass</b></p></th><th><p><b>Pathophysiology</b></p></th><th><p><b>Classic Exam &amp; Transillumination</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Hydrocele</b></p></td><td><p>Excess serous fluid inside <b>Tunica Vaginalis</b> (<i>Communicating</i> in infants via patent processus vaginalis -&gt; fluctuates in size; <i>Non-communicating</i> in adults -&gt; idiopathic or secondary to tumor/infection!)</p></td><td><p>Smooth, painless fluctuant scrotal swelling surrounding testis; <b>CAN get ABOVE it</b> (unlike inguinoscrotal hernia!); <b>BRILLIANTLY TRANSLUMINATES!</b></p></td><td><p><i>Infants (&lt; 1–2 yrs):</i> <b>Observe</b> (most close spontaneously; repair if persists &gt; 1–2 yrs!). <i>Adults:</i> Reassure or <b>Hydrocelectomy</b> if large/symptomatic (<b>DO NOT aspirate</b> -&gt; high recurrence/infection; <b>ALWAYS do Scrotal US first</b> in young men to exclude underlying <b>Testicular Tumor</b>!)</p></td></tr><tr><td><p><b>Spermatocele</b> <i>(Epididymal Cyst)</i></p></td><td><p>Painless sperm-filled retention cyst of <b>head of epididymis</b></p></td><td><p>Smooth, round, cystic lump felt <b>SEPARATE &amp; SUPERIOR/POSTERIOR to the testis</b>; <b>Transluminates!</b></p></td><td><p>Reassurance (excise ONLY if very large/painful)</p></td></tr><tr><td><p><b>Varicocele</b> <i>(#1 Surgically Correctable Cause of </i><i><b>Male Infertility</b></i><i>!)</i></p></td><td><p>Dilated <b>Pampiniform Venous Plexus </b>(<b>~85–90% LEFT-SIDED</b> because Left Gonadal Vein drains perpendicularly at 90° into Left Renal Vein!)</p></td><td><p><b>\"BAG OF WORMS\"</b> palpable above testis when <b>STANDING</b> (disappears when <b>SUPINE</b>!), dull aching scrotal heaviness! <b>CRITICAL RED FLAG:</b> <mark class=\"hl lab\"><b>Sudden-onset RIGHT-sided varicocele, OR varicocele that FAILS TO COLLAPSE when lying flat</b></mark> = <b>RULE OUT RETROPERITONEAL TUMOR / RENAL CELL CARCINOMA (IVC/Renal Vein Thrombus) via Abdominal CT/US!</b></p></td><td><p>Scrotal support/NSAIDs if asymptomatic; <b>Microsurgical Subinguinal Varicocelectomy </b>(or Embolization) if <b>infertility with abnormal semen analysis</b>, testicular atrophy (adolescents), or persistent pain!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u358\">← Case 4</button><button class=\"nv\" data-u=\"u360\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u360\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Priapism (ISCHEMIC VS. NON-ISCHEMIC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Priapism+%28ISCHEMIC+VS.+NON-ISCHEMIC%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Persistent, unintended penile erection lasting <b>&gt; 4 HOURS</b> unrelated to sexual interest/stimulation.</p><h3><b>2. Crucial Separation: Ischemic (Low-Flow) vs. Non-Ischemic (High-Flow)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Ischemic (Low-Flow / Veno-Occlusive) Priapism (~95% — TRUE UROLOGICAL EMERGENCY!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Etiology (Separated):</i> <b>Sickle Cell Disease</b> (#1 cause in children/young men!), Intracavernosal injection therapy (<b>Alprostadil/Papaverine</b> — common in Egypt!), Medications (<b>Trazodone [\"Traza-bone\"!], Antipsychotics, Sildenafil misuse</b>), Leukemia/Polycythemia, Idiopathic.</li>\n<li class=\"l2\"><i>Clinical &amp; Blood Gas:</i> <b>RIGID, PAINFUL</b> corpora cavernosa (soft glans!) + <mark class=\"hl lab\"><b>Cavernosal Blood Gas shows HYPOXIA, HYPERCAPNIA, &amp; ACIDOSIS (pO2 &lt; 30, pCO2 &gt; 60, pH &lt; 7.25)</b></mark> !</li>\n<li class=\"l2\"><i>Risk:</i> Irreversible corporal fibrosis &amp; <b>permanent Erectile Dysfunction</b> if untreated <b>&gt; 4–6 hours</b>!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Non-Ischemic (High-Flow / Arterial) Priapism (~5% — NOT an Emergency!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Etiology:</i> Blunt <b>perineal/straddle trauma</b> lacerating cavernosal artery -&gt; arteriocavernosal fistula!</li>\n<li class=\"l2\"><i>Clinical &amp; Blood Gas:</i> <mark class=\"hl dx\"><b>Semi-rigid, PAINLESS</b></mark> erection + <b>Bright-red arterial blood gas (pO2 &gt; 90, pH ~7.40)</b>!</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Ischemic Priapism (&gt; 4 Hours):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Penile dorsal nerve block -&gt; <b>Immediate Corporal Aspiration of dark ischemic blood</b> (with 19G butterfly needle) + Saline irrigation!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Intracavernosal Injection of Phenylephrine</b> (pure α1-agonist — 100–200 mcg q5 min while monitoring BP/HR!) -&gt; repeat until detumescence!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i>If Sickle Cell:</i> Add IV hydration, O2, analgesia (<b>exchange transfusion ONLY if standard aspiration/phenylephrine fails</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i>If Refractory:</i> Emergent surgical <b>Distal Cavernoglanular Shunt (Winter/Al-Ghorab Shunt)</b>!</span></p>\n<ul>\n<li class=\"l1\"><b>Non-Ischemic Priapism:</b> Observation + ice (most resolve spontaneously; selective arterial embolization if persistent!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u359\">← Case 5</button><button class=\"nv\" data-u=\"u361\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u361\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Phimosis, Paraphimosis &amp; Balanoposthitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Phimosis%2C+Paraphimosis+%26+Balanoposthitis\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Clinical Comparison</b></h3><ul>\n<li class=\"l1\"><b>Phimosis:</b> Inability to retract the foreskin (prepuce) proximally over the glans penis.</li>\n<li class=\"l2\"><i>Physiologic Phimosis:</i> <b>Normal in infants/boys &lt; 3–5 years!</b> (Resolves spontaneously — <b>NEVER forcibly retract!</b>).</li>\n<li class=\"l2\"><i>Pathologic Phimosis:</i> Fibrotic white scarred ring (Balanitis Xerotica Obliterans, recurrent balanitis in <b>Diabetics</b>!) -&gt; treat with <mark class=\"hl rx\"><b>Topical Betamethasone 0.05%</b></mark> × 4–6 wks or <b>Circumcision</b>.</li>\n<li class=\"l1\"><b>PARAPHIMOSIS (TRUE UROLOGICAL EMERGENCY!):</b> Retracted foreskin becomes <b>TRAPPED behind the coronal sulcus</b>, forming a tight constricting ring -&gt; venous/lymphatic engorgement -&gt; <b>arterial ischemia and Glans Penis Necrosis!</b></li>\n<li class=\"l2\"><i>Common Scenario:</i> Healthcare worker forgets to pull foreskin back forward after <mark class=\"hl rx\"><b>Foley catheter placement</b></mark> or exam!</li>\n<li class=\"l2\"><i>Emergency Treatment:</i> Penile block/analgesia -&gt; <b>Squeeze edematous glans firmly for 5–10 minutes</b> (use ice/osmotic sugar or gauze wrap to shrink swelling!) -&gt; <b>push glans INWARD with both thumbs while pulling foreskin FORWARD with fingers</b>! If manual reduction fails -&gt; <b>Emergent Dorsal Slit</b> under local anesthesia -&gt; later elective circumcision!</li>\n<li class=\"l1\"><b>Balanoposthitis:</b> Inflammation of glans (balanitis) and foreskin (posthitis) — <b>MOST COMMONLY </b><i><b>Candida albicans</b></i><b> in UNCONTROLLED DIABETICS!</b> -&gt; Check <mark class=\"hl mech\"><b>HbA1c/Glucose</b></mark> , keep clean/dry, <b>Topical Clotrimazole/Miconazole</b> (or oral Fluconazole)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u360\">← Case 6</button><button class=\"nv\" data-u=\"u362\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u362\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Fournierʼs Gangrene (PERINEAL NECROTIZING FASCIITIS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Fournier%CA%BCs+Gangrene+%28PERINEAL+NECROTIZING+FASCIITIS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Rapidly progressive, polymicrobial <b>necrotizing fasciitis of the perineum, scrotum, and external genitalia</b> (<b>TRUE SURGICAL EMERGENCY — 20–40% Mortality!</b>).</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Portal of Entry:</b> <b>Perianal/ischiorectal abscess</b>, <b>Urethral stricture/periurethral abscess</b>, Traumatic catheterization, Minor scrotal skin infection.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Host Predisposition:</b> <b>Uncontrolled Diabetes Mellitus (#1 Risk Factor! Including patients on SGLT2 inhibitors!)</b>, Obesity, Alcoholism, Immunosuppression.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Microbiology:</b> Synergistic polymicrobial Type I (<i>E. coli, Klebsiella, Bacteroides, Streptococci, S. aureus</i>).</span></p><h3><b>3. Clinical Picture (DO NOT WAIT FOR SKIN BLACKENING!)</b></h3><ul>\n<li class=\"l1\"><b>Severe perineal/scrotal pain OUT OF PROPORTION to early exam</b>, tense edematous erythema spreading rapidly onto abdominal wall (Colles’ -&gt; Scarpa’s fascia), <b>foul \"dishwater\" odor</b>, <b>subcutaneous crepitus (gas)</b>, <b>patches of dusky purple/black necrotic skin</b>, high fever, tachycardia, septic shock! <i>(Note: Testicles themselves are usually SPARED because their blood supply comes from the retroperitoneal aorta, not scrotal skin!)</i></li>\n</ul><h3><b>4. Treatment (MINUTES COUNT!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>EMERGENT RADICAL SURGICAL DEBRIDEMENT</b> of all necrotic fascia/skin in the OR (often requiring repeated 24-hr second-look debridements!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Immediate Triple Empirical IV Antibiotics:</b> <mark class=\"hl rx\"><b>Vancomycin (or Linezolid)</b></mark> + <mark class=\"hl rx\"><b>Piperacillin-Tazobactam (or Meropenem)</b></mark> + <mark class=\"hl rx\"><b>Clindamycin</b></mark> (antitoxin!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Aggressive ICU Fluid/Vasopressor Resuscitation</b> &amp; Insulin glycemic control!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u361\">← Case 7</button><button class=\"nv\" data-u=\"u363\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u363\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Urethritis &amp; Urethral Stricture</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urethritis+%26+Urethral+Stricture\">🔍 Search on Google</a></header><h3><b>A. Acute Urethritis (</b><b>STI</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <i><b>Neisseria gonorrhoeae</b></i> (profuse yellow-green purulent urethral discharge, 2–5 day incubation) <b>VS.</b> <b>Non-Gonococcal Urethritis — </b><i><b>Chlamydia trachomatis</b></i><b> (#1!)</b> / <i>Mycoplasma genitalium</i> (scant clear/mucoid discharge, 1–3 wk incubation).</li>\n<li class=\"l1\"><b>Diagnosis:</b> <b>Urine NAAT</b> (First-catch voided urine — <i>first 15–30 mL without wiping!</i>) for Gonorrhea &amp; Chlamydia + screen for <b>HIV &amp; Syphilis</b>!</li>\n<li class=\"l1\"><b>Treatment (Treat BOTH Unless Gonorrhea Ruled Out!):</b> <mark class=\"hl rx\"><b>Single IM Ceftriaxone 500 mg</b></mark> (1 g if ≥ 150 kg) <mark class=\"hl rx\"><b>PLUS Oral Doxycycline 100 mg BID × 7 days</b></mark> (preferred over Azithromycin due to resistance!) + <mark class=\"hl lab\"><b>Treat ALL sexual partners + Abstain 7 days</b></mark> !</li>\n</ul><h3><b>B. Urethral Stricture</b></h3><ul>\n<li class=\"l1\"><b>Etiology (Separated):</b> <b>(1) Iatrogenic</b> (traumatic Foley catheterization, prior TURP/cystoscopy — #1 in developed settings!), <b>(2) Trauma</b> (straddle injury -&gt; bulbar urethra; pelvic fracture -&gt; posterior urethra), <b>(3) Post-Infectious</b> (recurrent untreated Gonococcal urethritis), <b>(4) Lichen Sclerosus (BXO)</b>.</li>\n<li class=\"l1\"><b>Clinical &amp; Diagnosis:</b> Progressive <b>weak splayed/forked urinary stream</b>, straining, incomplete emptying, recurrent UTIs in a young/middle-aged man! Confirm with <b>Retrograde Urethrogram (RUG)</b> + Cystoscopy.</li>\n<li class=\"l1\"><b>Treatment:</b> <b>DVIU</b> (Direct Vision Internal Urethrotomy) for short (&lt; 1–2 cm) bulbar strictures -&gt; <b>Urethroplasty</b> (Gold Standard curative repair with buccal mucosa graft for recurrent/long strictures!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u362\">← Case 8</button><button class=\"nv\" data-u=\"u364\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u364\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Erectile Dysfunction (ED) &amp; Peyronieʼs Disease</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Erectile+Dysfunction+%28ED%29+%26+Peyronie%CA%BCs+Disease\">🔍 Search on Google</a></header><h3><b>A. Erectile Dysfunction (ED — Often the Earliest Warning Sign of Systemic Atherosclerosis!)</b></h3><ul>\n<li class=\"l1\"><b>Etiology (Separated — Organic [~80%] vs. Psychogenic [~20%]):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Vasculogenic (#1 Organic Cause!):</b> <mark class=\"hl dx\"><b>Atherosclerosis</b></mark> (HTN, DM, Dyslipidemia, Smoking — penile arteries are 1–2 mm wide, so <b>ED often precedes Coronary Artery Disease by 3–5 years!</b>) or venous leak.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Neurogenic / Endocrine / Drugs:</b> <b>Diabetic autonomic neuropathy</b>, Spinal cord/pelvic surgery (radical prostatectomy), <b>Hypogonadism</b> (low testosterone), <b>Hyperprolactinemia</b>, Drugs (<mark class=\"hl rx\"><b> Thiazides, older Beta-blockers, SSRIs, Spironolactone, Opioids</b></mark> !).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Psychogenic:</b> Performance anxiety, depression (<i>Clue:</i> <b>Sudden onset, situational, with INTACT morning/nocturnal erections!</b>).</span></p>\n<ul>\n<li class=\"l1\"><b>Workup:</b> <b>Morning Total Testosterone</b> (before 10 AM), <mark class=\"hl mech\"><b>HbA1c/Fasting Glucose</b></mark> , <b>Lipid Profile</b>, <mark class=\"hl mech\"><b>TSH</b></mark> ; assess <b>Cardiovascular Fitness</b>!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\">Lifestyle modification (stop smoking, exercise, weight loss).</li>\n<li class=\"l2\"><b>First-Line Drugs — PDE-5 Inhibitors (Sildenafil, Tadalafil, Vardenafil, Avanafil):</b> Require sexual stimulation to work (enhance nitric oxide/cGMP)!</li>\n<li class=\"l2\"><b>ABSOLUTE FATAL CONTRAINDICATION:</b> <mark class=\"hl rx\"><b>NEVER combine PDE-5 Inhibitors with NITRATES (Nitroglycerin/Isosorbide) or Riociguat</b></mark> -&gt; catastrophic refractory <mark class=\"hl lab\"><b>HYPOTENSIVE SHOCK</b></mark> ! (Caution with Alpha-blockers — separate by 4–6 hrs!).</li>\n<li class=\"l2\"><i>Second/Third-Line:</i> Vacuum erection device, Intracavernosal Alprostadil injections, <b>Penile Prosthesis Implant</b>.</li>\n</ul><h3><b>B. Peyronie’s Disease</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Localized fibrotic collagen plaque in the <b>Tunica Albuginea</b> (often linked to microvascular penile trauma &amp; <b>Dupuytren’s Contracture</b>!).</li>\n<li class=\"l1\"><b>Clinical:</b> <b>Painful erections</b> early + <b>palpable firm dorsal penile plaque</b> + <b>Penile Curvature</b> during erection!</li>\n<li class=\"l1\"><b>Treatment:</b> Wait 12–18 months for acute painful phase to stabilize (<mark class=\"hl rx\"><b> Vitamin E/Colchicine ineffective!</b></mark> ) -&gt; <b>Intralesional Collagenase (</b><i><b>Clostridium histolyticum</b></i><b>)</b> or <b>Surgical Plication / Plaque Grafting</b> once stable!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 14A — Urology (Cases 1–10 Complete!).</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u363\">← Case 9</button><button class=\"nv\" data-u=\"u365\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u365\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Bladder Carcinoma (UROTHELIAL VS. BILHARZIAL SQUAMOUS CELL CARCINOMA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bladder+Carcinoma+%28UROTHELIAL+VS.+BILHARZIAL+SQUAMOUS+CELL+CARCINOMA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Malignant neoplasm arising from the urinary bladder lining (<b>Urothelium</b>). In Egypt, bladder cancer holds unique dual epidemiology: <b>TCC</b> (Transitional Cell / Urothelial Carcinoma) and <b>Bilharzial SCC</b> (Squamous Cell Carcinoma).</p><h3><b>2. Etiology &amp; Risk Factors (Separated — Know Both Pathways!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Urothelial / Transitional Cell Carcinoma (TCC — &gt; 90% Globally &amp; Rising #1 in Urban Egypt):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Cigarette &amp; Shisha Smoking (#1 Overall Risk Factor — ~50% of cases!):</b> Aromatic amines excreted in urine.</li>\n<li class=\"l2\"><b>Occupational Carcinogens:</b> Aromatic amines (<b>Aniline dyes</b>, rubber, leather, textile, painting, aluminum workers).</li>\n<li class=\"l2\"><b>Medications &amp; Radiation:</b> <mark class=\"hl rx\"><b>Cyclophosphamide</b></mark> (acrolein metabolite -&gt; hemorrhagic cystitis -&gt; TCC!), Pelvic radiation, Phenacetin abuse.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Squamous Cell Carcinoma (SCC — Historically #1 in Rural Egypt, ~20–30%):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Chronic </b><i><b>Schistosoma haematobium</b></i><b> (Bilharziasis) Cystitis:</b> Chronic egg-induced inflammation -&gt; <b>Squamous Metaplasia -&gt; Invasive SCC!</b></li>\n<li class=\"l2\">Chronic indwelling Foley catheters (spinal cord injury patients!) or chronic bladder stones!</li>\n</ul><h3><b>3. Pathophysiology</b></h3><p>Carcinogens bathe the urothelium continuously, inducing field-effect dysplasia/carcinoma-in-situ (<b>CIS</b>). Crucially divided into <b>NMIBC</b> (Non-Muscle-Invasive Bladder Cancer — Ta, Tis, T1: ~75%) vs. <b>MIBC</b> (Muscle-Invasive Bladder Cancer — ≥ T2 invading detrusor muscle: ~25%, high metastatic potential!).</p><h3><b>4. Clinical Picture (THE GOLDEN UROLOGY RULE!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl dx\"><b>PAINLESS GROSS (VISIBLE) HEMATURIA</b></mark> (<b>Total hematuria</b> or terminal clots in an adult <b>&gt; 40 years</b> or smoker = <mark class=\"hl mech\"><b>BLADDER CANCER UNTIL PROVEN OTHERWISE! </b></mark>— even if a single episode stops spontaneously!).</li>\n<li class=\"l1\">Irritative voiding symptoms (dysuria, urgency, frequency — classic for <b>CIS</b> [Carcinoma in Situ] or Bilharzial SCC!).</li>\n<li class=\"l1\">Late signs: Pelvic mass, flank pain (ureteral obstruction/hydronephrosis), bone pain, weight loss.</li>\n</ul>\n<p><mark class=\"hl mech\"><b>5. Investigations (NEVER Attribute Painless Gross Hematuria in &gt; 40 Yrs to \"Just a UTI or Stone\" Without Cystoscopy!)</b></mark></p>\n<ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Urinalysis &amp; Urine Culture</b></mark> (rule out infection; <b>Urine Cytology</b> — high sensitivity for high-grade/CIS!).</li>\n<li class=\"l1\"><b>GOLD STANDARD DIAGNOSTIC PROCEDURE:</b> <mark class=\"hl mech\"><b>Cystoscopy + TURBT</b></mark> (Transurethral Resection of Bladder Tumor — must include <b>detrusor muscle</b> in biopsy to stage T1 vs. T2!).</li>\n<li class=\"l1\"><b>Upper Urinary Tract Evaluation (Rule out synchronous ureteral/renal pelvis tumors!):</b> <b>CT</b> (Computed Tomography) <mark class=\"hl mech\"><b>Urography</b></mark> (or Renal Ultrasound + MR Urography).</li>\n<li class=\"l1\"><b>Staging (If Muscle-Invasive):</b> <b>CT Chest, Abdomen &amp; Pelvis</b> + <mark class=\"hl mech\"><b>RFTs</b></mark> (Renal Function Tests).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Nephrolithiasis (painful colic!), Acute hemorrhagic cystitis (dysuria/pyuria!), <mark class=\"hl lab\"><b>BPH</b></mark> (Benign Prostatic Hyperplasia), <mark class=\"hl lab\"><b>RCC</b></mark> (Renal Cell Carcinoma), Bilharzial cystitis without malignancy, Glomerulonephritis (dysmorphic <b>RBCs</b> [Red Blood Cells] / casts).</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\">Clot urinary retention, Bilateral ureteric obstruction -&gt; <mark class=\"hl lab\"><b>Post-renal AKI/CKD</b></mark> (Acute/Chronic Kidney Injury), Severe anemia, Pelvic/lymph node/liver/lung/bone metastases.</li>\n</ul><h3><b>8. Treatment (Separated by Depth of Invasion!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Non-Muscle-Invasive (NMIBC — Ta, Tis, T1):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Complete TURBT</b> + Single post-op intravesical <b>Mitomycin C</b> or <b>Gemcitabine</b> (within 24 hrs!).</li>\n<li class=\"l2\"><i>High-Risk (T1, High-Grade, or CIS):</i> <b>Intravesical BCG</b> (Bacillus Calmette-Guérin) immunotherapy (weekly × 6 weeks + maintenance — induces T-cell destruction of tumor!) -&gt; Repeat <b>re-TURBT</b> at 4–6 wks for T1!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Muscle-Invasive (MIBC — ≥ T2) &amp; Bilharzial SCC:</b></span></p>\n<ul>\n<li class=\"l2\"><b>Neoadjuvant Cisplatin-Based Chemotherapy</b> (for TCC if fit!) <b>FOLLOWED BY Radical Cystectomy + Pelvic Lymph Node Dissection + Urinary Diversion</b> (<b>Ileal Conduit</b> or Orthotopic Neobladder)! <i>(Bilharzial SCC is poorly chemosensitive -&gt; Radical Cystectomy directly!)</i>.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Metastatic Disease:</b> Systemic <b>Enfortumab Vedotin + Pembrolizumab</b> (new first-line!) or Platinum chemotherapy + Immunotherapy.</span></p>\n<p><b>Clinical Pearl:</b> <i>A single painless episode of red urine in a 55-year-old Egyptian smoker MUST undergo </i><mark class=\"hl mech\"><i><b>Cystoscopy + CT Urography</b></i></mark><i> — even if urinalysis shows mild microscopic pyuria!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u364\">← Case 10</button><button class=\"nv\" data-u=\"u366\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u366\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Urinary Schistosomiasis (SCHISTOSOMA HAEMATOBIUM — EGYPTIAN CLASSIC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urinary+Schistosomiasis+%28SCHISTOSOMA+HAEMATOBIUM+%E2%80%94+EGYPTIAN+CLASSIC%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic parasitic infection of the <b>vesical and pelvic venous plexuses</b> caused by the blood fluke <i><b>Schistosoma haematobium</b></i>, endemic along the Nile River basin and rural agricultural areas in Egypt.</p><h3><b>2. Etiology &amp; Transmission</b></h3><ul>\n<li class=\"l1\"><b>Infective Stage:</b> <b>Cercariae</b> released by freshwater <b>Bulinus snails</b> penetrate human skin during wading/swimming/irrigation in contaminated Nile canals!</li>\n<li class=\"l1\">Adult worms reside in the <b>perivesical venous plexus</b>, laying <b>terminal-spined eggs</b> that penetrate the bladder wall into urine.</li>\n</ul><h3><b>3. Pathophysiology</b></h3><p>Eggs trapped in bladder and lower ureteric submucosa trigger intense <b>Type IV granulomatous inflammation</b> -&gt; <b>\"Sandy Patches\"</b> -&gt; progressive fibrosis, <b>calcification of bladder/ureteric walls</b>, distal ureteric strictures (hydronephrosis), <b>Squamous Metaplasia</b>, and <b>Bilharzial Bladder Carcinoma (SCC)</b>!</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><i>Acute (Swimmer’s Itch / Katayama Fever):</i> Cercarial dermatitis, fever, urticaria, hepatosplenomegaly, eosinophilia.</li>\n<li class=\"l1\"><i>Chronic Urinary Disease (Classic):</i> <b>Terminal Hematuria</b> (last few drops of urine bloody + dysuria in young rural males!), frequency, suprapubic ache; late complications include obstructive uropathy, recurrent <i>Salmonella</i> UTIs (chronic <i>Salmonella</i> carrier state!), and <b>painless hematuria / necrotic tissueuria</b> if SCC develops!</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Midday Urine Microscopy (10 AM – 2 PM, peak egg excretion!):</b> Identifies characteristic <b>oval eggs with a TERMINAL SPINE</b>!</li>\n<li class=\"l1\"><b>Labs:</b> Peripheral <b>Eosinophilia</b>, <i>Schistosoma</i> serology (ELISA), <mark class=\"hl mech\"><b>RFTs</b></mark> , Urinalysis.</li>\n<li class=\"l1\"><b>Imaging:</b> <b>KUB X-Ray</b> (classic <b>\"Eggshell\" Linear Calcification of the Bladder Wall</b> &amp; distal ureters!), <b>Renal/Bladder Ultrasound</b> (hydroureteronephrosis, irregular bladder wall thickening), <mark class=\"hl mech\"><b>Cystoscopy + Biopsy</b></mark> (<b>\"Sandy Patches\"</b>, Cystitis cystica/glandularis, rule out SCC!).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Bladder carcinoma (can coexist!), Urinary TB (sterile pyuria!), Bladder stones, Bacterial hemorrhagic cystitis, Nephrolithiasis.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Distal Ureteric Stricture -&gt; Hydronephrosis &amp; ESRD</b></mark> (End-Stage Renal Disease), <b>Bladder Squamous Cell Carcinoma</b>, Contracted \"thimble\" fibrotic bladder, Secondary bacterial/Salmonella UTIs, Bladder stones.</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Drug of Choice:</b> <b>Oral Praziquantel (40 mg/kg/day)</b> given in 1 or 2 divided doses for <b>1 day</b> (&gt; 85–95% cure rate; kills adult worms!).</li>\n<li class=\"l1\"><b>Reconstructive / Oncologic Care:</b> Ureteric reimplantation or stenting for fibrotic strictures; <mark class=\"hl mech\"><b>Cystoscopy surveillance</b></mark> for chronic cases with hematuria!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u365\">← Case 11</button><button class=\"nv\" data-u=\"u367\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u367\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Prostate Carcinoma</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Prostate+Carcinoma\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Malignant adenocarcinoma arising predominantly from the <b>PERIPHERAL ZONE (~75–80%)</b> of the prostate gland (<b>#1 Most Common Non-Skin Cancer in Men</b> and #2 cause of male cancer death!).</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Non-Modifiable Risk Factors:</b> <b>Advancing age (&gt; 50–65 yrs — #1!)</b>, <b>Family History</b> (1st-degree relative, <b>BRCA2</b> mutation!), African ancestry.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hormonal / Dietary:</b> Testosterone/DHT-driven growth; high animal-fat diet, obesity.</span></p><h3><b>3. Pathophysiology</b></h3><p>Androgen-dependent glandular adenocarcinoma spreading locally (seminal vesicles, bladder neck), lymphatically (pelvic nodes), and hematogenously via <b>Batson’s Paravertebral Venous Plexus</b> to the <b>Axial Skeleton (Lumbar Spine, Pelvis, Ribs)</b> producing classic <mark class=\"hl mech\"><b>OSTEOBLASTIC (sclerotic/dense) Bone Metastases</b></mark> !</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Early Localized Disease:</b> <b>COMPLETELY ASYMPTOMATIC!</b> (Because it arises in the <i>peripheral</i> zone away from the urethra — detected only by <mark class=\"hl mech\"><b>PSA</b></mark> or <mark class=\"hl lab\"><b>DRE</b></mark> !).</li>\n<li class=\"l1\"><b>Advanced / Metastatic Disease:</b> New lower back/pelvic bone pain, <b>Spinal Cord Compression</b> (emergency!), <b>LUTS</b> / hematuria (late local invasion), weight loss, anemia, bilateral leg edema.</li>\n<li class=\"l1\"><b>DRE:</b> <b>Hard, stony, irregular, asymmetric prostatic NODULE</b> (or fixed rock-hard gland!).</li>\n</ul><h3><b>5. Investigations &amp; Screening</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>PSA</b></mark> (Prostate-Specific Antigen) Screening: Discuss shared decision-making at <b>age 50–69</b> (earlier <b>age 40–45</b> if family history / BRCA2 / African descent!).</li>\n<li class=\"l2\"><i>Causes of False-Positive PSA Elevation:</i> <mark class=\"hl lab\"><b>BPH</b></mark> , <b>Prostatitis</b>, <b>UTI</b>, <b>Recent Ejaculation (48 hrs)</b>, <b>Urinary Retention / Foley Catheter</b>, <mark class=\"hl mech\"><b>Cystoscopy</b></mark> ! <i>(Routine gentle DRE minimally alters PSA!).</i></li>\n<li class=\"l1\"><b>Diagnosis:</b> <mark class=\"hl mech\"><b>Multiparametric MRI Prostate (PI-RADS)</b></mark> -&gt; <mark class=\"hl mech\"><b>TRUS-Guided (or MRI-Fusion) Prostate Biopsy</b></mark> (graded by <b>Gleason Score [6–10] / ISUP Grade Groups 1– 5</b>)!</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Staging (If High-Risk: PSA &gt; 20, Gleason ≥ 8, or Bone Pain):</b></mark> <b>Technetium-99m Bone Scan</b> (or <b>PSMA PET-CT</b>) + <b>CT Abdomen/Pelvis</b>!</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">BPH, Chronic/Granulomatous Prostatitis, Prostatic Calculi (mimic hard nodule on DRE!), Bladder cancer invading prostate.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\">Osteoblastic bone metastases &amp; pathologic fractures, <b>Malignant Spinal Cord Compression</b>, Bilateral ureteric obstruction (uremia), Urinary retention.</li>\n</ul><h3><b>8. Treatment (Stratified by Risk &amp; Life Expectancy!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Low-Risk Localized (Gleason 6, PSA &lt; 10):</b></mark> <b>Active Surveillance</b> (serial PSA, DRE, MRI, repeat biopsies — avoids unnecessary impotence/incontinence!).</li>\n<li class=\"l1\"><b>Intermediate / High-Risk Localized (Life Expectancy ≥ 10 Yrs):</b> <b>Radical Prostatectomy</b> (nerve-sparing if possible) <b>OR External Beam Radiation Therapy (EBRT) +/-ADT</b> (Androgen Deprivation Therapy).</li>\n<li class=\"l1\"><b>Metastatic Hormone-Sensitive Prostate Cancer:</b></li>\n<li class=\"l2\"><b>ADT (Medical or Surgical Castration):</b> <b>GnRH Agonist</b> (<b>Leuprolide / Goserelin</b> — <i>MUST give </i><i><b>Anti-Androgen [Bicalutamide] for first 2–4 weeks</b></i><i> to prevent </i><i><b>Testosterone \"Flare\"</b></i><i> causing bone pain/cord compression!</i>), OR <b>GnRH Antagonist</b> (<b>Degarelix / Relugolix</b> — NO flare!), OR <b>Bilateral Orchiectomy</b>!</li>\n<li class=\"l2\"><b>Intensification (Proven Survival Benefit!):</b> Add <mark class=\"hl rx\"><b>Novel Anti-Androgen (Abiraterone + Prednisone, Enzalutamide, Apalutamide)</b></mark> +/- <b>Docetaxel</b> chemotherapy!</li>\n<li class=\"l2\"><i>If Malignant Spinal Cord Compression:</i> <mark class=\"hl rx\"><b>STAT IV Dexamethasone + MRI Spine + Emergent Radiation / Neurosurgical Decompression</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u366\">← Case 12</button><button class=\"nv\" data-u=\"u368\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u368\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Renal Cell Carcinoma (RCC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal+Cell+Carcinoma+%28RCC%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Malignant adenocarcinoma arising from <b>proximal renal tubular epithelial cells</b> (<mark class=\"hl lab\"><b> Clear Cell RCC ~75–80%</b></mark> = #1 subtype).</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Lifestyle &amp; Environmental:</b> <b>Cigarette Smoking (#1 Modifiable Risk Factor!)</b>, <b>Obesity</b>, <b>Hypertension</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Renal / Genetic:</b> <mark class=\"hl rx\"><b>Acquired Cystic Kidney Disease (Chronic Dialysis patients!)</b></mark> , <b>VHL</b> (von Hippel-Lindau) syndrome (bilateral multifocal RCC + cerebellar hemangioblastomas + pheochromocytoma!).</span></p><h3><b>3. Pathophysiology &amp; Unique Vascular Spread</b></h3><p>Richly vascular tumor driven by <b>VHL gene loss -&gt; HIF-1α -&gt; massive VEGF overexpression</b>! Uniquely tends to invade directly into the <b>Renal Vein -&gt; Inferior Vena Cava (IVC)</b> up toward the Right Atrium!</p><h3><b>4. Clinical Picture (\"The Internist’s Tumor\" — Famous Paraneoplastic Syndromes!)</b></h3><ul>\n<li class=\"l1\"><b>Most Common Today:</b> <b>Incidental renal mass</b> found on abdominal Ultrasound/CT!</li>\n<li class=\"l1\"><b>Classic Triad (&lt; 10% — Indicates Advanced Disease!):</b> <b>(1) Flank Pain + (2) Gross Hematuria + (3) Palpable Flank/Abdominal Mass!</b></li>\n<li class=\"l1\"><b>Varicocele Clue:</b> <b>Sudden-onset NON-REDUCIBLE LEFT Varicocele</b> (left renal vein tumor thrombus!) or Right varicocele (IVC thrombus!).</li>\n<li class=\"l1\"><b>Paraneoplastic Syndromes:</b></li>\n<li class=\"l2\"><b>Erythrocytosis / Polycythemia</b> (ectopic <b>EPO</b> [Erythropoietin]).</li>\n<li class=\"l2\"><b>Hypercalcemia</b> (ectopic <b>PTHrP</b> [Parathyroid Hormone-Related Protein]).</li>\n<li class=\"l2\"><b>Hypertension</b> (renin) &amp; <b>Stauffer’s Syndrome</b> (non-metastatic elevated liver enzymes/ALP resolving after nephrectomy!).</li>\n<li class=\"l2\">Fever of unknown origin, weight loss, <b>Cannonball lung metastases</b>!</li>\n</ul><h3><b>5. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Imaging Gold Standard:</b> <b>Contrast-Enhanced CT Abdomen &amp; Pelvis</b> (or MRI to evaluate IVC thrombus!) + <b>CT Chest</b> (lungs = #1 metastatic site!). <b>CRITICAL RULE:</b> <b>DO NOT routinely needle-biopsy a typical resectable solid enhancing renal mass</b> — proceed directly to surgery! <i>(Bosniak III/IV complex renal cysts also require surgical resection!).</i></li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Localized Small Tumor (&lt; 4–7 cm):</i> <b>Partial Nephrectomy</b> (nephron-sparing — preserves kidney function!).</li>\n<li class=\"l2\"><i>Larger / Central / IVC Thrombus:</i> <b>Radical Nephrectomy</b> (+ IVC thrombectomy!).</li>\n<li class=\"l2\"><i>Metastatic RCC (</i><i><b>Chemo- &amp; Radio-Resistant!</b></i><i>):</i> <b>Immunotherapy (Pembrolizumab / Nivolumab + Ipilimumab) + VEGF Tyrosine Kinase Inhibitors (Axitinib, Cabozantinib, Sunitinib)</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u367\">← Case 13</button><button class=\"nv\" data-u=\"u369\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u369\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Testicular Tumors (GERM CELL TUMORS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Testicular+Tumors+%28GERM+CELL+TUMORS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Malignancy of the testis, representing the <b>#1 Most Common Solid Cancer in Young Men Aged 15 – 35 Years</b> (<b>&gt; 95% are Germ Cell Tumors [GCTs]</b>)!</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Cryptorchidism (Undescended Testis — #1 Risk Factor, 4–10× higher risk!):</b> Risk persists in BOTH testes even after early orchiopexy (though early surgery allows easier self-exam!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Genetic / Developmental:</b> <b>Klinefelter Syndrome (47,XXY)</b> (mediastinal GCTs), prior contralateral testicular cancer, family history, Testicular dysgenesis / infertility.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>PAINLESS, FIRM, HARD, NON-TENDER INTRATESTICULAR MASS / ENLARGEMENT</b></mark> (\"heavy dragging sensation\" in scrotum — <b>does NOT transilluminate!</b>).</li>\n<li class=\"l1\"><b>CRITICAL TRAP:</b> ~10–15% present with mild dull ache after minor trauma or mimic \"epididymitis\" -&gt; <b>IF \"epididymitis\" fails to resolve completely within 2–4 weeks, DO A SCROTAL ULTRASOUND IMMEDIATELY!</b></li>\n<li class=\"l1\">Check <b>Gynecomastia</b> (elevated β-hCG — Choriocarcinoma!) &amp; <b>Supraclavicular / Retroperitoneal Nodes</b>!</li>\n</ul><h3><b>4. Investigations (NEVER TRANS-SCROTAL BIOPSY!)</b></h3><ul>\n<li class=\"l1\"><b>Scrotal Ultrasound (First-Line):</b> Confirms solid hypoechoic <b>intratesticular</b> mass!</li>\n<li class=\"l1\"><b>Serum Tumor Markers (Draw BEFORE &amp; AFTER Orchiectomy!):</b></li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>AFP</b></mark> (Alpha-Fetoprotein): Elevated in <b>Yolk Sac Tumor</b> (non-seminoma) -&gt; <mark class=\"hl mech\"><b>PURE SEMINOMA NEVER ELEVATES AFP!</b></mark> <i>(If AFP is high, treat as Non-Seminoma regardless of biopsy!)</i></li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>β-hCG:</b></mark> Always elevated in <b>Choriocarcinoma</b>; mildly elevated in ~15% of Seminomas.</li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>LDH</b></mark> (Lactate Dehydrogenase): Reflects overall tumor burden!</li>\n<li class=\"l1\"><b>Staging:</b> <b>CT Chest, Abdomen &amp; Pelvis</b> (metastases spread to <b>Retroperitoneal [Para-aortic] Lymph Nodes</b> FIRST — NOT inguinal nodes unless scrotal skin was violated!).</li>\n</ul><h3><b>5. Treatment (&gt; 90–95% CURATIVE EVEN WHEN METASTATIC!)</b></h3><ul>\n<li class=\"l1\"><b>GOLDEN SURGICAL RULE:</b> <b>NEVER perform a Scrotal Needle Biopsy or Trans-Scrotal Incision</b> (contaminates scrotal lymphatics -&gt; inguinal metastases!) -&gt; Perform <b>RADICAL INGUINAL ORCHIECTOMY</b> (high ligation of spermatic cord at internal inguinal ring)! <i>(Offer </i><i><b>Sperm Banking</b></i><i> before chemotherapy/radiation!)</i></li>\n<li class=\"l1\"><b>Post-Orchiectomy:</b></li>\n<li class=\"l2\"><i>Seminoma (Radiosensitive!):</i> Surveillance, single-dose Carboplatin, or Para-aortic Radiation (early); <b>BEP Chemotherapy</b> (Bleomycin, Etoposide, Cisplatin) if advanced!</li>\n<li class=\"l2\"><i>Non-Seminomatous GCT (Teratoma, Embryonal, Yolk Sac, Choriocarcinoma):</i> Surveillance or <b>RPLND</b> (Retroperitoneal Lymph Node Dissection) or <b>BEP Chemotherapy</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u368\">← Case 14</button><button class=\"nv\" data-u=\"u370\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u370\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Renal Trauma &amp; Bladder Rupture</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal+Trauma+%26+Bladder+Rupture\">🔍 Search on Google</a></header><h3><b>A. Renal Trauma</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Blunt MVC/flank blow (#1) or penetrating stab/gunshot.</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ Red Flags Requiring Contrast CT Abdomen/Pelvis (Delayed Excretory Phase!):</b></mark></p></div></div><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Gross Hematuria</b> in ANY trauma patient, OR</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Microscopic Hematuria PLUS Shock (SBP &lt; 90 mmHg)</b></mark> , OR</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\">Rapid deceleration injury (fall from height/high-speed MVC — <b>renal pedicle avulsion may have NO hematuria!</b>), OR</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>ANY Hematuria in a Pediatric Trauma Patient</b>!</span></p>\n<ul>\n<li class=\"l1\"><b>Treatment:</b> <b>~85–90% of Blunt Renal Injuries (Grades I–IV) Are Managed NON-OPERATIVELY</b> (bed rest until gross hematuria clears, serial Hb, angioembolization for active bleed)! <b>Operate ONLY if:</b> Life-threatening hemodynamic instability, expanding/pulsatile retroperitoneal hematoma, or Grade V shattered kidney / renal pedicle avulsion!</li>\n</ul><h3><b>B. Bladder Rupture (Strongly Linked to Pelvic Fractures + Gross Hematuria!)</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis:</b> <b>CT Cystogram</b> (or Retrograde Cystogram — <i>must distend bladder to 300+ mL and take post-drainage film!</i>).</li>\n<li class=\"l1\"><b>CRITICAL SEPARATION — Management:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Extraperitoneal Bladder Rupture (~85% — Pelvic Bone Spicule Tear):</b> Contrast extravasates in <b>\"Flame-Shaped\"</b> pattern confined to pelvis -&gt; <b>NON-OPERATIVE: Large Foley Catheter Drainage ONLY for 10–14 Days</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Intraperitoneal Bladder Rupture (~15% — Blow to Full Bladder Dome):</b> Contrast outlines <b>loops of bowel &amp; paracolic gutters</b> -&gt; <b>IMMEDIATE SURGICAL REPAIR (Laparotomy/Laparoscopy) + Catheter Drainage</b> (prevents fatal urinary peritonitis!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u369\">← Case 15</button><button class=\"nv\" data-u=\"u371\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u371\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Urethral Trauma (ANTERIOR VS. POSTERIOR)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urethral+Trauma+%28ANTERIOR+VS.+POSTERIOR%29\">🔍 Search on Google</a></header><h3><b>1. Classic Triad of Suspected Urethral Injury (DO NOT INSERT A FOLEY CATHETER!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Blood at the Urethral Meatus</b> (#1 Most Important Sign!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Inability to Void</b> (distended bladder).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>High-Riding (\"Floating\") Prostate on DRE</b> (in posterior disruption) OR <b>Perineal/Scrotal \"Butterfly\" Hematoma</b> (in anterior bulbar injury).</span></p><h3><b>2. Two Distinct Mechanisms (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Posterior (Membranous/Prostatic) Urethral Injury:</b> <b>Pelvic Ring Fracture</b> (#1!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Anterior (Bulbar) Urethral Injury:</b> <b>Straddle Injury</b> (falling astride a bicycle bar, fence, or manhole cover!) crushing the bulbar urethra against the pubic symphysis!</span></p><h3><b>3. Emergency Management</b></h3><ul>\n<li class=\"l1\"><b>NEVER attempt blind transurethral Foley catheterization</b> (converts a partial tear into a complete transection!).</li>\n<li class=\"l1\">Perform <b>Retrograde Urethrogram (RUG)</b> FIRST!</li>\n<li class=\"l1\">If partial/complete disruption confirmed -&gt; Place <b>Suprapubic Catheter (SPC)</b> for urinary diversion -&gt; perform <b>delayed definitive Urethroplasty</b> 3–6 months later once pelvic hematoma resolves!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u370\">← Case 16</button><button class=\"nv\" data-u=\"u372\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u372\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Obstructive Uropathy &amp; Hydronephrosis (PUJ OBSTRUCTION)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Obstructive+Uropathy+%26+Hydronephrosis+%28PUJ+OBSTRUCTION%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology (Separated)</b></h3><p>Dilation of the renal pelvis and calyces (<b>Hydronephrosis</b>) due to impaired urinary drainage; if bilateral (or unilateral in a solitary kidney), causes <mark class=\"hl lab\"><b>Post-Renal AKI/CKD</b></mark> .</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Adults — Unilateral:</b> <b>Ureteric Stone (#1!)</b>, Retroperitoneal fibrosis (<b>IgG4 disease, Methysergide, Aortic aneurysm</b> — pulls ureters <i>medially</i>!), Ureteric/Pelvic tumor (Cervical/Colon cancer), Pregnancy (physiologic right &gt; left!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Adults — Bilateral:</b> <mark class=\"hl lab\"><b>BPH (#1!)</b></mark> , Prostate cancer, Cervical cancer invading trigone, Neurogenic bladder, Blocked Foley!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Children — Congenital:</b> <b>UPJ / PUJ (Ureteropelvic Junction) Obstruction (#1 Congenital Cause of Neonatal Hydronephrosis!)</b>, <b>VUR</b> (Vesicoureteral Reflux), <b>Posterior Urethral Valves</b> (bilateral in boys!).</span></p><h3><b>2. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Acute obstruction -&gt; severe flank colic; Chronic obstruction (e.g., UPJ obstruction) -&gt; asymptomatic flank fullness or <b>Dietl’s Crisis</b> (flank pain + vomiting triggered by drinking large fluid volumes!).</li>\n<li class=\"l1\"><b>Workup:</b> <b>Renal Ultrasound</b> (screens hydronephrosis), <mark class=\"hl mech\"><b>RFTs</b></mark> , <b>Non-Contrast CT</b> (adults — stones), <b>MAG-3 Diuretic Renogram (Lasix Renogram)</b> (Gold Standard to distinguish <b>true mechanical obstruction</b> from non-obstructive dilation!).</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Infected Obstructed Kidney (Hydronephrosis + Fever):</b> <mark class=\"hl rx\"><b>EMERGENT PCN</b></mark> (Percutaneous Nephrostomy) <b>or JJ Ureteral Stent</b> + IV Antibiotics!</li>\n<li class=\"l1\"><b>Symptomatic / Progressive PUJ Obstruction (Split function &lt; 40%):</b> <b>Anderson-Hynes Dismembered Pyeloplasty</b> (Laparoscopic/Robotic/Open)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u371\">← Case 17</button><button class=\"nv\" data-u=\"u373\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u373\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Pediatric Urology — Cryptorchidism, Hypospadias &amp; PUV</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Urology+%E2%80%94+Cryptorchidism%2C+Hypospadias+%26+PUV\">🔍 Search on Google</a></header><h3><b>1. Cryptorchidism (Undescended Testis)</b></h3><ul>\n<li class=\"l1\"><b>Key Distinction:</b> True Undescended Testis (cannot be pulled down into scrotum -&gt; high risk of <b>Infertility + Testicular Cancer [Seminoma]</b> + Torsion!) <b>VS. Retractile Testis</b> (hyperactive cremasteric reflex; CAN be gently brought to bottom of scrotum and stays temporarily -&gt; benign, monitor annually!).</li>\n<li class=\"l1\"><b>Treatment:</b> Wait up to <b>6 months</b> for spontaneous descent; if still undescended at <b>6–12 months</b> -&gt; Perform <mark class=\"hl mech\"><b>ORCHIOPEXY by 6–18 Months of Age</b></mark> ! <i>(NOTE: Early surgery preserves fertility &amp; enables palpation for cancer, though mild cancer risk remains! If </i><i><b>BILATERAL non-palpable testes</b></i><i> in newborn -&gt; </i><i><b>STAT Karyotype + 17-OH Progesterone</b></i><i> to rule out </i><i><b>Congenital Adrenal Hyperplasia [46,XX virilized female]</b></i><i> &amp; life-threatening salt-wasting crisis!)</i></li>\n</ul><h3><b>2. Hypospadias</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Ventral urethral meatus opening on underside of penis + <b>Ventral Chordee</b> (downward curvature) + <b>Dorsal Hooded Foreskin</b>!</li>\n<li class=\"l1\"><b>CRITICAL RULE:</b> <mark class=\"hl lab\"><b>DO NOT CIRCUMCISE A NEWBORN WITH HYPOSPADIAS!</b></mark> (The dorsal foreskin is needed later as graft tissue for surgical urethroplasty repair at 6–12 months!).</li>\n</ul><h3><b>3. Posterior Urethral Valves (PUV — #1 Cause of Bilateral Hydronephrosis &amp; CKD in Male Infants!)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Congenital obstructing urethral membranes in <b>boys ONLY</b>!</li>\n<li class=\"l1\"><b>Clues:</b> Antenatal <b>Oligohydramnios</b> + Bilateral hydroureteronephrosis + <b>\"Keyhole Sign\"</b> (thick-walled distended bladder + dilated posterior urethra on Ultrasound!), <b>weak dribbling urinary stream</b>, <b>palpable distended bladder</b>, urosepsis!</li>\n<li class=\"l1\"><b>Emergency Treatment:</b> Immediate bladder drainage via <b>small feeding tube / catheter</b> -&gt; stabilize electrolytes/creatinine -&gt; <b>Endoscopic Valve Ablation</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u372\">← Case 18</button><button class=\"nv\" data-u=\"u374\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u374\" hidden style=\"--c:#546e7a\"><button class=\"back\" data-p=\"14\">← Urology</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Nocturnal Enuresis &amp; Neurogenic Bladder</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nocturnal+Enuresis+%26+Neurogenic+Bladder\">🔍 Search on Google</a></header><h3><b>A. Primary Monosymptomatic Nocturnal Enuresis (Pediatric Bedwetting)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Involuntary nighttime wetting (≥ 2 nights/week) in a child <b>≥ 5 YEARS OLD</b> who has <b>never achieved consistent dryness</b> and has <b>NO daytime voiding symptoms</b>! <i>(Very common — ~15% of 5-yr-olds; strong family history!)</i></li>\n<li class=\"l1\"><b>CRITICAL RULE — Primary vs. Secondary Enuresis:</b> If a previously dry child (&gt; 6 mos dry) <b>suddenly restarts bedwetting (Secondary Enuresis)</b> -&gt; <b>RULE OUT UTI, TYPE 1 DIABETES MELLITUS (Polyuria!), CONSTIPATION, &amp; PSYCHOLOGICAL STRESS/ABUSE!</b></li>\n<li class=\"l1\"><b>Workup:</b> <mark class=\"hl mech\"><b>Urinalysis</b></mark> (check glucose, specific gravity, WBCs/nitrites) — no imaging needed if primary monosymptomatic!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Reassurance &amp; Behavioral Therapy (First-Line):</b> No shaming/punishment! Limit fluids 2 hrs before bed, void right before sleep, treat constipation, reward dry nights.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Enuresis Bedwetting Alarm (Most Effective Long-Term Cure — ~65–75%!).</b></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Desmopressin (DDAVP — Synthetic ADH):</b> Rapid short-term control (sleepovers/camps — <i>warn child NOT to drink excess water before bed due to hyponatremia risk!</i>). <i>(Avoid Imipramine due to cardiac toxicity!).</i></span></p><h3><b>B. Neurogenic Bladder</b></h3><ul>\n<li class=\"l1\"><b>Two Main Patterns (Separated):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Upper Motor Neuron (Spinal Cord Injury above S2–S4 / MS / Stroke):</b> <b>Spastic Hyperreflexic Detrusor</b> -&gt; small capacity, urgency, incontinence, high pressure (<b>risk of VUR &amp; renal damage!</b>) -&gt; Treat with <b>Antimuscarinics (Oxybutynin/Solifenacin)</b> or <b>Intradetrusor Botulinum Toxin</b> + <b>Clean Intermittent Catheterization (CIC)</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Lower Motor Neuron (Cauda Equina / Spina Bifida / Severe Diabetic Neuropathy):</b> <b>Flaccid Atonic Bladder</b> -&gt; huge capacity, high PVR, <b>overflow incontinence </b>-&gt; Treat with <b>Clean Intermittent Self-Catheterization (CIC)</b> every 4–6 hours (<b>Gold Standard — avoids permanent Foley UTI/stone complications!</b>).</span></p>\n<p class=\"muted\"><i>End of Part 14B — Urology (20 Cases Complete!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u373\">← Case 19</button></nav></article>"});
